actions.script:
organizationPartyId = '__NO_ORGANIZATION__'
def selected = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!selected || selected in ['_NA_','__NO_ORGANIZATION__']) return
if (!ec.user.isInGroup('ADMIN')) {
    def partyId = ec.user.userAccount?.partyId
    if (!partyId) return
    def membership = ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo')
            .parameters([partyId:partyId]).call()
    if (!membership?.userOrgIds?.contains(selected)) return
}
if (ec.entity.find('mantle.party.Organization').condition('partyId',selected).one()) organizationPartyId = selected

totalExpiryValue = 0G; expiringAssets = []; categoryOptions = []; supplierOptions = []
tierCounts = [all:0, expired:0, d30:0, d3160:0, d6190:0, after90:0]
summary = [riskValue:0G, riskUnits:0G, riskCount:0, expiredValue:0G, expiredUnits:0G, expiredCount:0]
def selected = scope.organizationPartyId
if (selected == '__NO_ORGANIZATION__' || (organizationPartyId && organizationPartyId != selected)) return
def validBucket = (daysBucket ?: '').toString().trim()
def validWithin = (withinDays ?: '90').toString().trim()
if (!(validBucket in ['', 'all', 'expired', '0-30', '31-60', '61-90', '90+']) || !(validWithin in ['7','30','60','90','all','expired'])) { ec.message.addError('Choose a valid expiry period.'); return }
def zone = java.time.ZoneId.of(ec.user.userAccount?.timeZone ?: java.util.TimeZone.getDefault().ID)
def today = ec.user.nowTimestamp.toInstant().atZone(zone).toLocalDate()
import java.sql.Timestamp
def assetList = ec.entity.find("mantle.product.asset.Asset")
    .condition("ownerPartyId", selected).condition("assetTypeEnumId", "AstTpInventory")
    .condition("statusId", "AstAvailable")
    .condition("expiryDate", org.moqui.entity.EntityCondition.NOT_EQUAL, null)
    .condition("quantityOnHandTotal", org.moqui.entity.EntityCondition.GREATER_THAN, BigDecimal.ZERO).list()

// ZE-INV-011 (IV-111): batch-load products + suppliers up front to avoid an N+1 (was one Product
// query per asset + per-order supplier queries, so the page slowed in proportion to the number
// of expiring lots). Now 3 set-based lookups regardless of asset count.
def _pids = assetList.collect { it.productId }.findAll { it }.unique()
def _prodMap = [:]
if (_pids) ec.entity.find("mantle.product.Product").condition("productId", "in", _pids).condition("ownerPartyId", selected).list().each { _prodMap[it.productId] = it }

def _oids = assetList.collect { it.acquireOrderId }.findAll { it }.unique()
def _orderVendor = [:]
if (_oids) ec.entity.find("mantle.order.OrderPart").condition("orderId", "in", _oids).condition("customerPartyId", selected).disableAuthz().list().each {
    if (it.vendorPartyId && !_orderVendor.containsKey(it.orderId)) _orderVendor[it.orderId] = it.vendorPartyId
}
def _vids = _orderVendor.values().findAll { it }.unique()
def _vendorName = [:]
if (_vids) ec.entity.find("mantle.party.PartyDetail").condition("partyId", "in", _vids).disableAuthz().list().each {
    _vendorName[it.partyId] = it.organizationName ?: ((it.firstName ?: '') + ' ' + (it.lastName ?: '')).trim()
}

def _nowMs = ec.user.nowTimestamp.getTime()
// ZE-INV expiry §9: resolve each product's primary category name (one batched pair of finds) so the
// list can show SKU (pseudoId) + category — real data from the model, no fabrication.
def _ecCat = [:]
def _ecPids = _prodMap.keySet()
if (_ecPids) {
    ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productId", "in", new ArrayList(_ecPids)).disableAuthz().list().each {
        if (!_ecCat.containsKey(it.productId)) _ecCat[it.productId] = it.productCategoryId
    }
    def _ecCids = _ecCat.values().findAll { it }.unique()
    def _ecCName = [:]
    if (_ecCids) ec.entity.find("mantle.product.category.ProductCategory").condition("productCategoryId", "in", _ecCids).condition("ownerPartyId", "in", [selected, "_NA_"]).disableAuthz().list().each { _ecCName[it.productCategoryId] = it.categoryName ?: it.productCategoryId }
    def _ecResolved = [:]
    for (def _ecK : new ArrayList(_ecCat.keySet())) { _ecResolved[_ecK] = _ecCName[_ecCat[_ecK]] ?: '' }
    _ecCat = _ecResolved
}
List expList = []
for (def asset : assetList) {
    def product = _prodMap[asset.productId]
    if (product == null) { continue }
    // supplier for PO-received lots (acquireOrderId -> OrderPart.vendorPartyId -> party name)
    def _vid = asset.acquireOrderId ? _orderVendor[asset.acquireOrderId] : null
    def supplierName = _vid ? (_vendorName[_vid] ?: '') : ''
    // value at cost (valuationRate) -> acquireCost -> MRP; tag the basis
    def _pos = { v -> (v != null && (v as BigDecimal).signum() > 0) ? (v as BigDecimal) : null }
    def valRate = asset.valuationRate != null && asset.valuationRate >= 0 ? asset.valuationRate : (asset.acquireCost != null && asset.acquireCost >= 0 ? asset.acquireCost : null)
    def valBasis = (valRate != null) ? 'cost' : null
    if (valRate == null) { valRate = _pos(asset.mrpAmount) ?: _pos(product.mrpAmount); if (valRate != null) valBasis = 'MRP' }
    if (valRate == null) { valRate = BigDecimal.ZERO; valBasis = 'unvalued' }
    def qoh = asset.quantityOnHandTotal ?: BigDecimal.ZERO
    def _days = (int)java.time.temporal.ChronoUnit.DAYS.between(today, (asset.expiryDate instanceof java.sql.Date ? asset.expiryDate.toLocalDate() : java.time.Instant.ofEpochMilli(asset.expiryDate.getTime()).atZone(zone).toLocalDate()))
    expList.add([
        assetId: asset.assetId, productId: asset.productId, productName: product?.productName ?: 'Unknown', supplierName: supplierName,
        stockVersion: asset.lastUpdatedStamp?.getTime()?.toString(), facilityId:asset.facilityId, uqcEnumId:product.uqcEnumId,
        pseudoId: product?.pseudoId ?: '', category: (_ecCat[asset.productId] ?: ''),
        expiryDate: asset.expiryDate, daysToExpiry: _days, quantity: qoh,
        value: valRate.multiply(qoh), valuationRate: valRate, valueBasis: valBasis,
        batchNumber: asset.batchNumber ?: 'N/A'
    ])
}

// expiry-risk §6: distinct category + supplier options from the FULL org list (stable regardless
// of the current filter selection, so the dropdowns don't lose options when a filter is applied).
categoryOptions = expList.collect { it.category }.findAll { it }.unique().sort().collect { [v: it] }
supplierOptions = expList.collect { it.supplierName }.findAll { it }.unique().sort().collect { [v: it] }

// search + category + supplier filters
def _search = (searchText ?: '').toString().trim().toLowerCase()
if (_search) expList = expList.findAll { r ->
    (((r.productName ?: '') + ' ' + (r.assetId ?: '') + ' ' + (r.batchNumber ?: '') + ' ' + (r.supplierName ?: '') + ' ' + (r.pseudoId ?: '')).toLowerCase().contains(_search) )
}
def _catF = (categoryFilter ?: '').toString().trim()
if (_catF) expList = expList.findAll { r -> (r.category ?: '') == _catF }
def _supF = (supplierFilter ?: '').toString().trim()
if (_supF) expList = expList.findAll { r -> (r.supplierName ?: '') == _supF }

// expiry-risk §7: tier counts over the search/category/supplier scope (BEFORE the tier/within filter)
// so every chip shows a stable count within the active scope.
def _deT = { r -> (r.daysToExpiry != null) ? (r.daysToExpiry as Integer) : 999 }
tierCounts = [
    all:     expList.size(),
    expired: expList.count { _deT(it) < 0 },
    d30:     expList.count { def d = _deT(it); d >= 0 && d <= 30 },
    d3160:   expList.count { def d = _deT(it); d > 30 && d <= 60 },
    d6190:   expList.count { def d = _deT(it); d > 60 && d <= 90 },
    after90: expList.count { _deT(it) > 90 }
]

for (def r : expList) {
    if (r.daysToExpiry < 0) { summary.expiredValue += r.value; summary.expiredUnits += r.quantity; summary.expiredCount++ }
    else if (r.daysToExpiry <= 90) { summary.riskValue += r.value; summary.riskUnits += r.quantity; summary.riskCount++ }
}

// §7 tier (range) filter from the chips, OR the cumulative 'within N days' dropdown (§6)
def _bucket = (daysBucket ?: '').toString().trim()
def _within = validWithin
if (_bucket) {
    expList = expList.findAll { r -> def d = _deT(r)
        (_bucket == 'expired') ? (d < 0) :
        ((_bucket == '0-30') ? (d >= 0 && d <= 30) :
        ((_bucket == '31-60') ? (d > 30 && d <= 60) :
        ((_bucket == '61-90') ? (d > 60 && d <= 90) :
        ((_bucket == '90+') ? (d > 90) : true))))
    }
} else if (_within && _within != 'all') {
    expList = expList.findAll { r -> (_within == 'expired') ? (r.daysToExpiry < 0) : (r.daysToExpiry <= (_within as Integer)) }
}

BigDecimal totalVal = BigDecimal.ZERO
for (def r : expList) { totalVal = totalVal.add(r.value ?: BigDecimal.ZERO) }

// sort (leading '-' = desc, whitelist, nulls last)
def _ob = (orderByField ?: 'expiryDate').toString()
def _desc = _ob.startsWith('-'); def _fld = _desc ? _ob.substring(1) : _ob
if (!(_fld in ['assetId','productName','pseudoId','batchNumber','supplierName','expiryDate','daysToExpiry','quantity','value'])) _fld = 'expiryDate'
def _nc = { a, b -> (a == null && b == null) ? 0 : (a == null ? 1 : (b == null ? -1 : (a <=> b))) }
expList.sort { x, y -> def c = _nc(x[_fld], y[_fld]); (c ? (_desc ? -c : c) : (x.assetId <=> y.assetId)) }

totalExpiryValue = totalVal
expiringAssets = expList

def _tot = java.math.BigDecimal.ZERO
for (it in _stiList) {
    def q = (it.quantity ?: 0) as java.math.BigDecimal
    def u = (it.unitAmount ?: 0) as java.math.BigDecimal
    _tot = _tot.add(q.multiply(u))
}
// ZE-INV-IV-075: E-Way is also required for an inter-state move (source & destination facilities
// under DIFFERENT GSTINs), not only for value > ₹50,000.
boolean _inter = false
def _stx = ec.entity.find("zenith.erp.inventory.StockTransfer").condition("stockTransferId", stockTransferId).one()
if (_stx?.fromFacilityId && _stx?.toFacilityId) {
    def _ff = ec.entity.find("mantle.facility.Facility").condition("facilityId", _stx.fromFacilityId).one()
    def _tf = ec.entity.find("mantle.facility.Facility").condition("facilityId", _stx.toFacilityId).one()
    _inter = (_ff?.facilityGstin && _tf?.facilityGstin && _ff.facilityGstin.take(2) != _tf.facilityGstin.take(2))
}
totalValue = _tot
ewayBillRequired = ((_tot.compareTo(new java.math.BigDecimal("50000")) > 0) || _inter) ? "Y" : "N"

if.script:
// placeholder IGST invoice (never finalized in the draft flow): void it rather than hard-delete
def inv = ec.entity.find("mantle.account.invoice.Invoice").condition("invoiceId", stx.igstInvoiceId).one()
if (inv && (inv.fromPartyId != stx.organizationPartyId || !(inv.statusId in ['InvoiceInProcess','InvoiceCancelled']))) {
    ec.message.addError('This transfer is linked to an issued or foreign invoice and cannot be deleted.'); return
}
if (inv && inv.statusId == 'InvoiceInProcess') { inv.statusId = 'InvoiceCancelled'; inv.update() }

actions.script:
def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
def transfer = ec.entity.find('zenith.erp.inventory.StockTransfer').condition('stockTransferId', stockTransferId).one()
allowed = !!(activeOrg && activeOrg != '_NA_' && transfer && transfer.organizationPartyId == activeOrg)

allowed = true
if (!ec.user.isInGroup('ADMIN')) {
    def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
    def g = ec.entity.find('zenith.erp.inventory.GatePass')
            .condition('gatePassId', gatePassId).disableAuthz().one()
    if (g == null || !activeOrg || activeOrg == '_NA_' || g.organizationPartyId != activeOrg) {
        allowed = false
    }
}

allowed = true
if (!ec.user.isInGroup('ADMIN')) {
    def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
    def fac = ec.entity.find('mantle.facility.Facility')
            .condition('facilityId', facilityId).disableAuthz().one()
    if (fac == null || !activeOrg || activeOrg == '_NA_' || fac.ownerPartyId != activeOrg) {
        allowed = false
    }
}

allowed = true
if (!ec.user.isInGroup('ADMIN')) {
    def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
    def prod = ec.entity.find('mantle.product.Product')
            .condition('productId', productId).disableAuthz().one()
    if (prod == null || !activeOrg || activeOrg == '_NA_' || prod.ownerPartyId != activeOrg) {
        allowed = false
    }
}

def prod = ec.entity.find("mantle.product.Product").condition("productId", productId).one()
if (prod == null) { ec.message.addError("Product not found."); return }
def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
if (!ec.user.isInGroup('ADMIN') && (!activeOrg || prod.ownerPartyId != activeOrg)) {
    ec.message.addError("Product not found for your account."); return
}
def refs = []
if (ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("productId", productId).count() > 0) refs.add("POS bills")
if (ec.entity.find("mantle.account.invoice.InvoiceItem").condition("productId", productId).count() > 0) refs.add("invoices")
if (ec.entity.find("mantle.order.OrderItem").condition("productId", productId).count() > 0) refs.add("orders")
def assets = ec.entity.find("mantle.product.asset.Asset").condition("productId", productId).list()
def hasStock = false
for (a in assets) {
    if (((a.quantityOnHandTotal ?: 0) as BigDecimal) != 0) { hasStock = true; break }
    if (ec.entity.find("mantle.product.asset.AssetDetail").condition("assetId", a.assetId).count() > 0) { hasStock = true; break }
}
if (hasStock) refs.add("stock records")
if (refs) {
    ec.message.addError("Cannot delete: this product is on " + refs.join(", ") + " and must stay for history/audit.")
    return
}
// audit: an irreversible delete on a live system must be reconstructable from the logs
ec.logger.warn("delete#Product AUDIT: user " + (ec.user.username ?: "?") + " permanently deleting product " + productId + " (org " + prod.ownerPartyId + "): " + groovy.json.JsonOutput.toJson(new HashMap(prod)))
try {
    ec.entity.find("zenith.erp.inventory.ProductEditorImage").condition("productId", productId).condition("organizationPartyId",prod.ownerPartyId).deleteAll()
    ec.entity.find("mantle.product.ProductPrice").condition("productId", productId).deleteAll()
    ec.entity.find("zenith.erp.pos.PosProductModePrice").condition("productId", productId).deleteAll()
    ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productId", productId).deleteAll()
    ec.entity.find("mantle.product.ProductIdentification").condition("productId", productId).deleteAll()
    for (a in assets) { try { a.delete() } catch (Exception ignored) { } }
    ec.entity.find("mantle.product.Product").condition("productId", productId).deleteAll()
    ec.message.addMessage("Product deleted.")
} catch (Exception e) {
    ec.logger.warn("delete#Product blocked for " + productId + ": " + e.message)
    ec.message.addError("Cannot delete this product - it is referenced by other records (e.g. variants or stock).")
}
